import re
from decimal import Decimal, ROUND_HALF_UP


class InsufficientFunds(Exception):
    pass


class Ledger:
    _amount_re = re.compile(r'^[0-9]+(?:\.[0-9]{1,2})?$')
    _fee = Decimal('1.50')

    def __init__(self, overdraft_limit='0.00'):
        self._overdraft_limit = self._parse_amount(overdraft_limit, allow_zero=True)
        self._balance = Decimal('0.00')
        self._history = []

    def _parse_amount(self, amount, allow_zero=False):
        if not isinstance(amount, str):
            raise TypeError("amount must be a string")
        if not self._amount_re.match(amount):
            raise ValueError("amount must be a non-negative decimal with at most two fractional digits")
        value = Decimal(amount)
        if not allow_zero and value == 0:
            raise ValueError("amount must be non-zero")
        return value

    def _fmt(self, value):
        return str(value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))

    def deposit(self, amount):
        value = self._parse_amount(amount)
        self._balance += value
        self._history.append(('deposit', self._fmt(value)))

    def withdraw(self, amount):
        value = self._parse_amount(amount)
        tentative = self._balance - value
        if tentative < -self._overdraft_limit:
            raise InsufficientFunds("withdrawal would exceed overdraft limit")
        self._balance = tentative
        self._history.append(('withdraw', self._fmt(value)))
        if self._balance < 0:
            self._balance -= self._fee
            self._history.append(('fee', self._fmt(self._fee)))

    def balance(self):
        return self._fmt(self._balance)

    def history(self):
        return list(self._history)
