import heapq
from collections.abc import Iterable


class CycleError(ValueError):
    def __init__(self, nodes: list[str]):
        super().__init__(f"cycle detected involving nodes: {nodes}")
        self.nodes = nodes


def _build_graph(nodes: Iterable[str], edges: list[tuple[str, str]]):
    node_set = set(nodes)
    deduped_edges = list(dict.fromkeys(edges))
    for before, after in deduped_edges:
        if before not in node_set:
            raise ValueError(f"unknown node {before!r}")
        if after not in node_set:
            raise ValueError(f"unknown node {after!r}")

    adjacency: dict[str, list[str]] = {node: [] for node in node_set}
    indegree: dict[str, int] = {node: 0 for node in node_set}
    for before, after in deduped_edges:
        adjacency[before].append(after)
        indegree[after] += 1

    return node_set, adjacency, indegree


def topo_order(nodes: Iterable[str], edges: list[tuple[str, str]]) -> list[str]:
    node_set, adjacency, indegree = _build_graph(nodes, edges)

    heap = [node for node, deg in indegree.items() if deg == 0]
    heapq.heapify(heap)

    result: list[str] = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for successor in adjacency[node]:
            indegree[successor] -= 1
            if indegree[successor] == 0:
                heapq.heappush(heap, successor)

    if len(result) != len(node_set):
        remaining = sorted(node_set - set(result))
        raise CycleError(remaining)

    return result


def layers(nodes: Iterable[str], edges: list[tuple[str, str]]) -> list[list[str]]:
    node_set, adjacency, indegree = _build_graph(nodes, edges)

    remaining = set(node_set)
    result: list[list[str]] = []

    while remaining:
        layer = sorted(node for node in remaining if indegree[node] == 0)
        if not layer:
            remaining_sorted = sorted(remaining)
            raise CycleError(remaining_sorted)

        result.append(layer)
        for node in layer:
            remaining.remove(node)
            for successor in adjacency[node]:
                indegree[successor] -= 1

    return result
