def to_roman(n):
    if type(n) is bool or not isinstance(n, int):
        raise TypeError("to_roman requires an int")
    if n < 1 or n > 3999:
        raise ValueError("to_roman input must be between 1 and 3999")
    values = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")
    ]
    result = []
    for value, symbol in values:
        while n >= value:
            result.append(symbol)
            n -= value
    return "".join(result)


def from_roman(s):
    if type(s) is not str:
        raise TypeError("from_roman requires a str")
    if s == "":
        raise ValueError("empty string is not a Roman numeral")

    grammar = [
        ("M", 1000), ("CM", 900), ("D", 500), ("CD", 400),
        ("C", 100), ("XC", 90), ("L", 50), ("XL", 40),
        ("X", 10), ("IX", 9), ("V", 5), ("IV", 4), ("I", 1)
    ]

    total = 0
    pos = 0
    for symbol, value in grammar:
        while s.startswith(symbol, pos):
            total += value
            pos += len(symbol)

    if pos != len(s):
        raise ValueError("not a canonical Roman numeral")

    if to_roman(total) != s:
        raise ValueError("not a canonical Roman numeral")

    return total


def is_roman(s):
    try:
        from_roman(s)
        return True
    except (TypeError, ValueError):
        return False
