def _validate(intervals):
    for iv in intervals:
        if len(iv) != 2:
            raise ValueError("Each interval must be a 2-item sequence")
        start, end = iv
        if not isinstance(start, (int, float)) or not isinstance(end, (int, float)):
            raise ValueError("Interval endpoints must be numbers")
        if start > end:
            raise ValueError("Interval start must not be greater than end")


def _to_tuples(intervals):
    return [(iv[0], iv[1]) for iv in intervals if iv[0] < iv[1]]


def merge(intervals):
    _validate(intervals)
    cleaned = _to_tuples(intervals)
    if not cleaned:
        return []
    cleaned.sort(key=lambda iv: iv[0])
    result = [cleaned[0]]
    for start, end in cleaned[1:]:
        last_start, last_end = result[-1]
        if start <= last_end:
            if end > last_end:
                result[-1] = (last_start, end)
        else:
            result.append((start, end))
    return result


def subtract(a, b):
    _validate(a)
    _validate(b)
    merged_a = merge(a)
    merged_b = merge(b)
    result = []
    i = 0
    for start, end in merged_a:
        current_start = start
        while current_start < end and i < len(merged_b):
            b_start, b_end = merged_b[i]
            if b_end <= current_start:
                i += 1
                continue
            if b_start >= end:
                break
            if b_start > current_start:
                result.append((current_start, b_start))
            current_start = max(current_start, b_end)
            if b_end <= end:
                i += 1
            else:
                break
        if current_start < end:
            result.append((current_start, end))
    return result


def total_length(intervals):
    _validate(intervals)
    merged = merge(intervals)
    return sum(end - start for start, end in merged)
