def spans(prices: list) -> list:
    if not isinstance(prices, list):
        raise TypeError("prices must be a list")
    result = []
    stack = []  # stack of (price, span) for a monotonic decreasing sequence
    for p in prices:
        if p is None:
            result.append(0)
            stack.clear()
            continue
        if isinstance(p, bool) or not isinstance(p, (int, float)):
            raise TypeError("prices elements must be int, float, or None")
        span = 1
        while stack and stack[-1][0] <= p:
            span += stack.pop()[1]
        stack.append((p, span))
        result.append(span)
    return result


def next_greater(prices: list) -> list:
    if not isinstance(prices, list):
        raise TypeError("prices must be a list")
    n = len(prices)
    result = [-1] * n
    stack = []  # indices with decreasing prices, reset on None
    for i in range(n - 1, -1, -1):
        p = prices[i]
        if p is None:
            stack.clear()
            result[i] = -1
            continue
        if isinstance(p, bool) or not isinstance(p, (int, float)):
            raise TypeError("prices elements must be int, float, or None")
        while stack and prices[stack[-1]] <= p:
            stack.pop()
        if stack:
            result[i] = stack[-1]
        else:
            result[i] = -1
        stack.append(i)
    return result


def widest_span(prices: list) -> tuple:
    if not isinstance(prices, list):
        raise TypeError("prices must be a list")
    sp = spans(prices)
    best_idx = -1
    best_span = 0
    for i in range(len(sp)):
        if sp[i] >= best_span:
            best_idx = i
            best_span = sp[i]
    return (best_idx, best_span)
