def expand_field(field: str, lo: int, hi: int) -> list[int]:
    if not field or not field.strip():
        raise ValueError("invalid cron: empty field")
    items = field.split(",")
    result = set()
    for item in items:
        if not item:
            raise ValueError("invalid cron: empty item")
        base, sep, step_part = item.partition("/")
        if sep:
            if not step_part or not step_part.isdigit():
                raise ValueError("invalid cron: invalid step")
            step = int(step_part)
            if step == 0:
                raise ValueError("invalid cron: step must be >= 1")
        else:
            step = 1
        if base == "*":
            start, end = lo, hi
        elif base.isdigit():
            start = end = int(base)
        elif "-" in base:
            a_str, dash, b_str = base.partition("-")
            if not a_str or not b_str or not a_str.isdigit() or not b_str.isdigit():
                raise ValueError("invalid cron: invalid range")
            a, b = int(a_str), int(b_str)
            if a > b:
                raise ValueError("invalid cron: range start greater than end")
            if not (lo <= a <= hi) or not (lo <= b <= hi):
                raise ValueError("invalid cron: value out of range")
            start, end = a, b
        else:
            raise ValueError("invalid cron: invalid item")
        if not (lo <= start <= hi) or not (lo <= end <= hi):
            raise ValueError("invalid cron: value out of range")
        for value in range(start, end + 1, step):
            result.add(value)
    return sorted(result)


def _parse_expr(expr: str) -> tuple[list[int], list[int]]:
    if not expr or not expr.strip():
        raise ValueError("invalid cron: empty expression")
    fields = expr.strip().split()
    if len(fields) != 2:
        raise ValueError("invalid cron: expression must have exactly two fields")
    minute_field, hour_field = fields
    minutes = expand_field(minute_field, 0, 59)
    hours = expand_field(hour_field, 0, 23)
    return minutes, hours


def cron_matches(expr: str, hour: int, minute: int) -> bool:
    minutes, hours = _parse_expr(expr)
    return hour in hours and minute in minutes


def next_match(expr: str, hour: int, minute: int) -> tuple[int, int]:
    minutes, hours = _parse_expr(expr)
    if not minutes or not hours:
        raise ValueError("invalid cron: no matching times")
    # Same hour: look for a minute strictly after the current one.
    for m in minutes:
        if m > minute:
            if hour in hours:
                return (hour, m)
    # No later minute in the current hour; scan forward through hours cyclically.
    for h_offset in range(1, 25):
        h = (hour + h_offset) % 24
        if h in hours:
            return (h, minutes[0])
    raise ValueError("invalid cron: no matching times")
