class Scheduler:
    def __init__(self):
        self._tasks = {}
        self._insertion_counter = 0

    def add(self, name, priority, after=()):
        if name in self._tasks:
            raise ValueError(f"Task {name!r} already added")
        after_set = set(after)
        unknown = after_set - self._tasks.keys()
        if unknown:
            raise KeyError(f"Unknown dependency: {unknown.pop()!r}")
        self._tasks[name] = {
            "priority": priority,
            "after": after_set,
            "status": "pending",
            "insertion": self._insertion_counter,
        }
        self._insertion_counter += 1

    def next(self):
        completed = {
            name for name, info in self._tasks.items()
            if info["status"] == "completed"
        }
        ready = [
            (info["priority"], -info["insertion"], name)
            for name, info in self._tasks.items()
            if info["status"] == "pending" and info["after"].issubset(completed)
        ]
        if not ready:
            return None
        ready.sort(reverse=True)
        _, _, name = ready[0]
        self._tasks[name]["status"] = "running"
        return name

    def complete(self, name):
        if name not in self._tasks:
            raise KeyError(f"Unknown task: {name!r}")
        if self._tasks[name]["status"] != "running":
            raise ValueError(f"Task {name!r} is not running")
        self._tasks[name]["status"] = "completed"

    def remaining(self):
        return sum(
            1 for info in self._tasks.values() if info["status"] != "completed"
        )
