import bisect
from typing import List, Tuple


def _validate_intervals(intervals: List[Tuple[int, int, int]]) -> None:
    if not isinstance(intervals, list):
        raise TypeError("intervals must be a list")
    for item in intervals:
        if not isinstance(item, tuple):
            raise TypeError("each interval must be a tuple")
        if len(item) != 3:
            raise ValueError("each interval must be a length-3 tuple")
        start, end, weight = item
        for value in (start, end, weight):
            if isinstance(value, bool) or not isinstance(value, int):
                raise TypeError("start, end, and weight must be int")
        if start >= end:
            raise ValueError("start must be less than end")


def best_schedule(intervals: List[Tuple[int, int, int]]) -> Tuple[int, int]:
    _validate_intervals(intervals)

    n = len(intervals)
    if n == 0:
        return (0, 0)

    # Sort by end time without modifying the original list or tuples.
    sorted_intervals = sorted(intervals, key=lambda x: x[1])

    ends = [interval[1] for interval in sorted_intervals]

    # dp[i] = best (total_weight, -interval_count) using intervals among the first i sorted intervals.
    # We use negative count so that larger weight wins, and for equal weight smaller count wins.
    dp: List[Tuple[int, int]] = [(0, 0)] * (n + 1)

    for i in range(1, n + 1):
        start, end, weight = sorted_intervals[i - 1]

        # Find the last interval ending <= current start.
        j = bisect.bisect_right(ends, start, lo=0, hi=i - 1)

        # Option 1: skip this interval.
        skip = dp[i - 1]

        # Option 2: take this interval.
        prev_weight, prev_neg_count = dp[j]
        take_weight = prev_weight + weight
        take_neg_count = prev_neg_count - 1
        take = (take_weight, take_neg_count)

        # Choose lexicographically better: higher weight, then smaller count (more negative count).
        if take > skip:
            dp[i] = take
        else:
            dp[i] = skip

    total_weight, neg_count = dp[n]
    # If total weight is not positive, return (0, 0).
    if total_weight <= 0:
        return (0, 0)

    return (total_weight, -neg_count)


def max_parallel(intervals: List[Tuple[int, int, int]]) -> int:
    _validate_intervals(intervals)

    if len(intervals) == 0:
        return 0

    events = []
    for start, end, _ in intervals:
        # (time, kind). kind: 1 for start (active after processing), 0 for end (inactive before start).
        # End events come before start events at the same time so touching intervals do not overlap.
        events.append((start, 1))
        events.append((end, 0))

    events.sort(key=lambda x: (x[0], x[1]))

    active = 0
    max_active = 0
    for _, kind in events:
        if kind == 1:
            active += 1
            if active > max_active:
                max_active = active
        else:
            active -= 1

    return max_active
