        # live element counts per heap value (for lazy deletion)
        self._delayed_low: Dict[int, int] = {}
        self._delayed_high: Dict[int, int] = {}
        self._low_size = 0
        self._high_size = 0
        self._total = 0

    def _validate_int(self, x) -> int:
        if isinstance(x, bool) or not isinstance(x, int):
            raise TypeError("value must be int")
        return x

    def _prune_low(self) -> None:
        while self._low:
            val = -self._low[0]
            if self._delayed_low.get(val, 0):
                heapq.heappop(self._low)
                self._delayed_low[val] -= 1
                if self._delayed_low[val] == 0:
                    del self._delayed_low[val]
            else:
                break

    def _prune_high(self) -> None:
        while self._high:
            val = self._high[0]
            if self._delayed_high.get(val, 0):
                heapq.heappop(self._high)
                self._delayed_high[val] -= 1
                if self._delayed_high[val] == 0:
                    del self._delayed_high[val]
            else:
                break

    def _rebalance(self) -> None:
        # Ensure sizes are balanced:
        # low_size and high_size differ by at most 1.
        # When total is odd, the preferred side has one more element.
        self._prune_low()
        self._prune_high()

        if self._total == 0:
            return

        if self._total % 2 == 1:
            target = (self._total // 2) + 1 if self.prefer_high else self._total // 2 + 1
            # target is always (total//2 + 1) for odd; preferred side gets the extra
            if self.prefer_high:
                # high should have one more
                while self._high_size > self._low_size + 1:
                    self._prune_high()
                    val = heapq.heappop(self._high)
                    self._delayed_high[val] = self._delayed_high.get(val, 0) + 1
                    self._high_size -= 1
                    heapq.heappush(self._low, -val)
                    self._low_size += 1
                    self._prune_low()
                while self._low_size > self._high_size:
                    self._prune_low()
                    val = -heapq.heappop(self._low)
                    self._delayed_low[val] = self._delayed_low.get(val, 0) + 1
                    self._low_size -= 1
                    heapq.heappush(self._high, val)
                    self._high_size += 1
                    self._prune_high()
            else:
                # low should have one more
                while self._low_size > self._high_size + 1:
                    self._prune_low()
                    val = -heapq.heappop(self._low)
                    self._delayed_low[val] = self._delayed_low.get(val, 0) + 1
                    self._low_size -= 1
                    heapq.heappush(self._high, val)
                    self._high_size += 1
                    self._prune_high()
                while self._high_size > self._low_size:
                    self._prune_high()
                    val = heapq.heappop(self._high)
                    self._delayed_high[val] = self._delayed_high.get(val, 0) + 1
                    self._high_size -= 1
                    heapq.heappush(self._low, -val)
                    self._low_size += 1
                    self._prune_low()
        else:
            # even: sizes must be equal
            while self._low_size > self._high_size:
                self._prune_low()
                val = -heapq.heappop(self._low)
                self._delayed_low[val] = self._delayed_low.get(val, 0) + 1
                self._low_size -= 1
                heapq.heappush(self._high, val)
                self._high_size += 1
                self._prune_high()
            while self._high_size > self._low_size:
                self._prune_high()
                val = heapq.heappop(self._high)
                self._delayed_high[val] = self._delayed_high.get(val, 0) + 1
                self._high_size -= 1
                heapq.heappush(self._low, -val)
                self._low_size += 1
                self._prune_low()

        self._prune_low()
        self._prune_high()

    def add(self, x: int) -> None:
        x = self._validate_int(x)

        if not self._low:
            heapq.heappush(self._low, -x)
            self._low_size += 1
        else:
            self._prune_low()
            low_top = -self._low[0]
            if x <= low_top:
                heapq.heappush(self._low, -x)
                self._low_size += 1
            else:
                heapq.heappush(self._high, x)
                self._high_size += 1

        self._total += 1
        self._rebalance()

    def remove(self, x: int) -> None:
        x = self._validate_int(x)

        if self._total == 0:
            raise ValueError("not present")

        self._prune_low()
        self._prune_high()

        low_top = -self._low[0] if self._low else None

        if low_top is not None and x <= low_top:
            # x should be in low
            if x not in self._delayed_low and (-x not in self._low or self._low.count(-x) <= self._delayed_low.get(x, 0)):
                # Need a robust presence check: try to find x in low heap live
                found = False
                for val in self._low:
                    real = -val
                    if real == x and self._delayed_low.get(real, 0) == 0:
                        found = True
                        break
                    if real == x:
                        # delayed exists, but maybe there is another copy
                        pass
                if not found:
                    # maybe in high?
                    found_high = False
                    for val in self._high:
                        if val == x and self._delayed_high.get(val, 0) == 0:
                            found_high = True
                            break
                    if found_high:
                        self._delayed_high[x] = self._delayed_high.get(x, 0) + 1
                        self._high_size -= 1
                    else:
                        raise ValueError("not present")
                else:
                    self._delayed_low[x] = self._delayed_low.get(x, 0) + 1
                    self._low_size -= 1
            else:
                self._delayed_low[x] = self._delayed_low.get(x, 0) + 1
                self._low_size -= 1
        else:
            # x should be in high
            if x not in self._delayed_high and (x not in self._high or self._high.count(x) <= self._delayed_high.get(x, 0)):
                found = False
                for val in self._high:
                    if val == x and self._delayed_high.get(val, 0) == 0:
                        found = True
                        break
                if not found:
                    found_low = False
                    for val in self._low:
                        real = -val
                        if real == x and self._delayed_low.get(real, 0) == 0:
                            found_low = True
                            break
                    if found_low:
                        self._delayed_low[x] = self._delayed_low.get(x, 0) + 1
                        self._low_size -= 1
                    else:
                        raise ValueError("not present")
                else:
                    self._delayed_high[x] = self._delayed_high.get(x, 0) + 1
                    self._high_size -= 1
            else:
                self._delayed_high[x] = self._delayed_high.get(x, 0) + 1
                self._high_size -= 1

        self._total -= 1
        self._rebalance()

    def median(self) -> int:
        if self._total == 0:
            raise LookupError("median of empty MedianTracker")

        self._prune_low()
        self._prune_high()

        if self._total % 2 == 1:
            if self.prefer_high:
                return self._high[0]
            else:
                return -self._low[0]
        else:
            if self.prefer_high:
                return self._high[0]
            else:
                return -self._low[0]

    def __len__(self) -> int:
        return self._total
