def render(template: str, values: dict) -> str:
    n = len(template)
    result = []
    i = 0
    while i < n:
        ch = template[i]
        if ch == '\\':
            if i + 1 < n and template[i + 1] == '\\':
                result.append('\\')
                i += 2
            elif i + 2 < n and template[i + 1] == '{' and template[i + 2] == '{':
                result.append('{{')
                i += 3
            else:
                result.append('\\')
                i += 1
        elif ch == '{' and i + 1 < n and template[i + 1] == '{':
            start = i
            j = i + 2
            found = False
            while j + 1 < n:
                if template[j] == '}' and template[j + 1] == '}':
                    found = True
                    break
                j += 1
            if not found:
                raise ValueError(f'unclosed placeholder at {start}')
            content = template[i + 2:j]
            pipe_pos = content.find('|')
            if pipe_pos == -1:
                key_part = content
                default_part = None
            else:
                key_part = content[:pipe_pos]
                default_part = content[pipe_pos + 1:]
            key = key_part.strip(' ')
            if default_part is None:
                default = None
            else:
                default = default_part.strip(' ')
            segments = key.split('.')
            for seg in segments:
                if not seg or not (('A' <= seg[0] <= 'Z') or ('a' <= seg[0] <= 'z') or seg[0] == '_'):
                    raise ValueError(f'bad key: {key}')
                for c in seg[1:]:
                    if not (('A' <= c <= 'Z') or ('a' <= c <= 'z') or ('0' <= c <= '9') or c == '_'):
                        raise ValueError(f'bad key: {key}')
            missing = False
            cur = values
            for idx, seg in enumerate(segments):
                if not isinstance(cur, dict) or seg not in cur:
                    missing = True
                    break
                cur = cur[seg]
                if idx == len(segments) - 1 and cur is None:
                    missing = True
            if missing:
                if default is not None:
                    result.append(default)
                else:
                    raise KeyError(f'missing: {key}')
            else:
                if cur is True:
                    result.append('true')
                elif cur is False:
                    result.append('false')
                else:
                    result.append(str(cur))
            i = j + 2
        else:
            result.append(ch)
            i += 1
    return ''.join(result)
