import re
from functools import cmp_to_key

# Strict regex for a single semantic version line. Anchored to start/end,
# rejects surrounding/trailing whitespace or newline.
_VERSION_RE = re.compile(
    r"""
    (?P<prefix>[vV]?)                       # optional single leading v/V
    (?P<major>0|[1-9]\d*)                   # major, no leading zeros
    \.
    (?P<minor>0|[1-9]\d*)                   # minor, no leading zeros
    \.
    (?P<patch>0|[1-9]\d*)                   # patch, no leading zeros
    (?:-(?P<prerelease>[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?   # prerelease
    (?:\+(?P<build>[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?        # build
    \Z                                      # end of string, no newline/space
    """,
    re.VERBOSE,
)


def _parse_prerelease(prerelease: str) -> tuple[int | str, ...]:
    parts: list[int | str] = []
    for ident in prerelease.split("."):
        if not ident:
            raise ValueError("invalid version: empty prerelease identifier")
        if ident.isdigit():
            if len(ident) > 1 and ident[0] == "0":
                raise ValueError(
                    "invalid version: numeric prerelease identifier has leading zero"
                )
            parts.append(int(ident))
        else:
            if not all(ch.isascii() and (ch.isalnum() or ch == "-") for ch in ident):
                raise ValueError(
                    "invalid version: invalid character in prerelease identifier"
                )
            parts.append(ident)
    return tuple(parts)


def _parse_build(build: str) -> str:
    for ident in build.split("."):
        if not ident:
            raise ValueError("invalid version: empty build identifier")
        if not all(ch.isascii() and (ch.isalnum() or ch == "-") for ch in ident):
            raise ValueError("invalid version: invalid character in build identifier")
    return build


def parse_version(text: str) -> tuple[int, int, int, tuple[int | str, ...], str | None]:
    if not isinstance(text, str):
        raise ValueError("invalid version: input must be a string")
    match = _VERSION_RE.match(text)
    if not match:
        raise ValueError("invalid version: does not match semantic version grammar")
    major = int(match.group("major"))
    minor = int(match.group("minor"))
    patch = int(match.group("patch"))
    prerelease_str = match.group("prerelease")
    build_str = match.group("build")
    prerelease: tuple[int | str, ...] = ()
    build: str | None = None
    if prerelease_str is not None:
        prerelease = _parse_prerelease(prerelease_str)
    if build_str is not None:
        build = _parse_build(build_str)
    return (major, minor, patch, prerelease, build)


def compare_versions(a: str, b: str) -> int:
    a_parsed = parse_version(a)
    b_parsed = parse_version(b)

    # Compare core version numerically.
    for part_a, part_b in zip(a_parsed[:3], b_parsed[:3]):
        if part_a < part_b:
            return -1
        if part_a > part_b:
            return 1

    # Core versions are equal; compare prerelease.
    a_pre = a_parsed[3]
    b_pre = b_parsed[3]

    if not a_pre and not b_pre:
        return 0
    if not a_pre and b_pre:
        return 1
    if a_pre and not b_pre:
        return -1

    # Both have prerelease identifiers.
    for ident_a, ident_b in zip(a_pre, b_pre):
        a_is_num = isinstance(ident_a, int)
        b_is_num = isinstance(ident_b, int)
        if a_is_num and b_is_num:
            if ident_a < ident_b:
                return -1
            if ident_a > ident_b:
                return 1
        elif not a_is_num and not b_is_num:
            if ident_a < ident_b:
                return -1
            if ident_a > ident_b:
                return 1
        else:
            # One numeric, one alphanumeric: numeric ranks lower.
            return -1 if a_is_num else 1

    # All shared identifiers equal; longer list wins.
    if len(a_pre) < len(b_pre):
        return -1
    if len(a_pre) > len(b_pre):
        return 1
    return 0


def sort_versions(versions: list[str]) -> list[str]:
    return sorted(versions, key=cmp_to_key(compare_versions))
