def parse_ini(text: str) -> dict:
    if not text:
        return {}

    raw_lines = text.split('\n')
    lines = [line[:-1] if line.endswith('\r') else line for line in raw_lines]

    result: dict[str, dict[str, str]] = {}
    current_section: str | None = None
    recent_key: str | None = None

    for i, line in enumerate(lines, start=1):
        stripped = line.strip()

        # Rule 1: blank/whitespace-only line
        if stripped == '':
            recent_key = None
            continue

        # Rule 2: comment line
        first_non_ws = stripped[0]
        if first_non_ws in ';#':
            continue

        # Rule 3: continuation line
        if line[0] in ' \t':
            if recent_key is None or current_section is None:
                raise ValueError(f'line {i}: continuation without a key to continue')
            if result[current_section][recent_key] == '':
                result[current_section][recent_key] = stripped
            else:
                result[current_section][recent_key] += ' ' + stripped
            continue

        # Rule 4: section header
        if stripped.startswith('[') and stripped.endswith(']'):
            section_name = stripped[1:-1].strip().lower()
            if section_name not in result:
                result[section_name] = {}
            current_section = section_name
            recent_key = None
            continue

        # Rule 5: key-value line
        if '=' not in line:
            raise ValueError(f'line {i}: missing "=" in key-value line')

        key, value = line.split('=', 1)
        key = key.strip().lower()
        value = value.strip()

        if key == '':
            raise ValueError(f'line {i}: empty key')

        if current_section is None:
            current_section = ''
            if '' not in result:
                result[''] = {}

        if key in result[current_section]:
            raise ValueError(f'duplicate key {key!r} in section {current_section!r}')

        result[current_section][key] = value
        recent_key = key

    # Rule 6: quote stripping
    for section in result.values():
        for k, v in section.items():
            if len(v) >= 2 and v.startswith('"') and v.endswith('"'):
                section[k] = v[1:-1]

    return result
