def _parse_version(version: str) -> tuple[int, ...]:
    s = version.strip()
    if not s:
        raise ValueError("empty version")
    parts = s.split(".")
    for p in parts:
        if not p:
            raise ValueError("empty version component")
        if not p.isdigit():
            raise ValueError("non-numeric version component")
    return tuple(int(p) for p in parts)


def _compare(v1: tuple[int, ...], v2: tuple[int, ...]) -> int:
    length = max(len(v1), len(v2))
    for i in range(length):
        a = v1[i] if i < len(v1) else 0
        b = v2[i] if i < len(v2) else 0
        if a < b:
            return -1
        if a > b:
            return 1
    return 0


def _upper_bound_compatible(version: tuple[int, ...]) -> tuple[int, ...]:
    if len(version) < 2:
        raise ValueError("~= requires at least two version components")
    upper = list(version[:-1])
    upper[-1] += 1
    return tuple(upper)


def _parse_spec(spec: str) -> list[tuple[str, tuple[int, ...]]]:
    s = spec.strip()
    if not s:
        return []
    clauses = []
    for raw_clause in s.split(","):
        clause = raw_clause.strip()
        if not clause:
            raise ValueError("empty clause")
        for op in ("==", "!=", ">=", "<=", "~=", ">", "<"):
            if clause.startswith(op):
                version_str = clause[len(op):].strip()
                if not version_str:
                    raise ValueError("missing version in clause")
                parsed = _parse_version(version_str)
                if op == "~=":
                    _upper_bound_compatible(parsed)  # validate multi-component
                clauses.append((op, parsed))
                break
        else:
            raise ValueError("clause without operator")
    return clauses


def satisfies(version: str, spec: str) -> bool:
    parsed_version = _parse_version(version)
    for op, target in _parse_spec(spec):
        cmp = _compare(parsed_version, target)
        if op == "==" and cmp != 0:
            return False
        if op == "!=" and cmp == 0:
            return False
        if op == ">=" and cmp < 0:
            return False
        if op == "<=" and cmp > 0:
            return False
        if op == ">" and cmp <= 0:
            return False
        if op == "<" and cmp >= 0:
            return False
        if op == "~=":
            upper = _upper_bound_compatible(target)
            if _compare(parsed_version, target) < 0:
                return False
            if _compare(parsed_version, upper) >= 0:
                return False
    return True


def max_satisfying(versions: list[str], spec: str) -> str | None:
    parsed_versions = []
    for v in versions:
        parsed_versions.append((v, _parse_version(v)))
    clauses = _parse_spec(spec)
    best_original = None
    best_parsed = None
    best_index = None
    for index, (original, parsed) in enumerate(parsed_versions):
        if not all(_clause_matches(parsed, clause) for clause in clauses):
            continue
        if (best_parsed is None or
            _compare(parsed, best_parsed) > 0 or
            (_compare(parsed, best_parsed) == 0 and index < best_index)):
            best_original = original
            best_parsed = parsed
            best_index = index
    return best_original


def _clause_matches(parsed: tuple[int, ...], clause: tuple[str, tuple[int, ...]]) -> bool:
    op, target = clause
    cmp = _compare(parsed, target)
    if op == "==":
        return cmp == 0
    if op == "!=":
        return cmp != 0
    if op == ">=":
        return cmp >= 0
    if op == "<=":
        return cmp <= 0
    if op == ">":
        return cmp > 0
    if op == "<":
        return cmp < 0
    if op == "~=":
        upper = _upper_bound_compatible(target)
        return _compare(parsed, target) >= 0 and _compare(parsed, upper) < 0
    raise ValueError("unknown operator")
