import re
from collections import deque
from decimal import Decimal, ROUND_HALF_EVEN


class FifoBook:
    _PRICE_RE = re.compile(r'^[0-9]+(\.[0-9]{1,4})?$')

    def __init__(self):
        self._lots = deque()
        self._holdings = 0
        self._realized = Decimal('0.00')
        self._cost_basis = Decimal(0)

    @staticmethod
    def _validate_qty(qty):
        if isinstance(qty, bool) or isinstance(qty, float) or not isinstance(qty, int):
            raise TypeError('qty must be int')
        if qty <= 0:
            raise ValueError('qty must be positive')

    @staticmethod
    def _validate_price(price):
        if not isinstance(price, str):
            raise TypeError('price must be str')
        if not FifoBook._PRICE_RE.match(price):
            raise ValueError('invalid price format')

    def buy(self, qty, price):
        self._validate_qty(qty)
        self._validate_price(price)
        price_decimal = Decimal(price)
        self._lots.append([qty, price, price_decimal])
        self._holdings += qty
        self._cost_basis += price_decimal * qty

    def sell(self, qty, price):
        self._validate_qty(qty)
        self._validate_price(price)
        if qty > self._holdings:
            raise ValueError('insufficient holdings')
        sell_price = Decimal(price)
        remaining = qty
        total_pnl = Decimal(0)
        consumed_cost = Decimal(0)
        while remaining > 0:
            lot = self._lots[0]
            lot_qty, _, lot_price = lot
            if lot_qty <= remaining:
                consumed = lot_qty
                self._lots.popleft()
            else:
                consumed = remaining
                lot[0] = lot_qty - consumed
            pnl = (sell_price - lot_price) * consumed
            total_pnl += pnl
            consumed_cost += lot_price * consumed
            remaining -= consumed
        quantized_pnl = total_pnl.quantize(Decimal('0.01'), rounding=ROUND_HALF_EVEN)
        self._holdings -= qty
        self._cost_basis -= consumed_cost
        self._realized += quantized_pnl
        return quantized_pnl

    def realized(self):
        return self._realized

    def holdings(self):
        return self._holdings

    def lots(self):
        return [(lot[0], lot[1]) for lot in self._lots]

    def cost_basis(self):
        return self._cost_basis.quantize(Decimal('0.01'), rounding=ROUND_HALF_EVEN)
