                nxt = raw[i + 1]
                if nxt == "0":
                    chars.append("~")
                elif nxt == "1":
                    chars.append("/")
                else:
                    raise ValueError("Invalid escape sequence in pointer token")
                i += 2
            else:
                chars.append(ch)
                i += 1
        decoded.append("".join(chars))
    return decoded


def resolve(doc: Any, pointer: str) -> Any:
    tokens = _decode_pointer(pointer)
    current = doc
    for token in tokens:
        if isinstance(current, dict):
            if token not in current:
                raise KeyError(token)
            current = current[token]
        elif isinstance(current, list):
            if token == "-":
                raise KeyError(token)
            if token == "0":
                index = 0
            else:
                if not token.isdigit() or token[0] == "0":
                    raise KeyError(token)
                index = int(token)
            if index >= len(current):
                raise KeyError(token)
            current = current[index]
        else:
            raise KeyError(token)
    return current


def set_value(doc: Any, pointer: str, value: Any) -> Any:
    new_doc = copy.deepcopy(doc)
    if pointer == "":
        return value
    tokens = _decode_pointer(pointer)
    parent_tokens = tokens[:-1]
    final_token = tokens[-1]
    current = new_doc
    for token in parent_tokens:
        if isinstance(current, dict):
            if token not in current:
                raise KeyError(token)
            current = current[token]
        elif isinstance(current, list):
            if token == "-":
                raise KeyError(token)
            if token == "0":
                index = 0
            else:
                if not token.isdigit() or token[0] == "0":
                    raise KeyError(token)
                index = int(token)
            if index >= len(current):
                raise KeyError(token)
            current = current[index]
        else:
            raise KeyError(token)
    if isinstance(current, dict):
        current[final_token] = value
    elif isinstance(current, list):
        if final_token == "-":
            current.append(value)
        elif final_token == "0":
            current[0] = value
        else:
            if not final_token.isdigit() or final_token[0] == "0":
                raise KeyError(final_token)
            index = int(final_token)
            if index > len(current):
                raise KeyError(final_token)
            if index == len(current):
                current.append(value)
            else:
                current[index] = value
    else:
        raise KeyError(final_token)
    return new_doc
