def validate_stream(events) -> None:
    events = list(events)
    seen = set()
    for event in events:
        event_id = event[1]
        if event_id in seen:
            raise ValueError(f"duplicate id: {event_id}")
        seen.add(event_id)
    for i in range(1, len(events)):
        prev = events[i - 1]
        curr = events[i]
        if (curr[0], curr[1]) <= (prev[0], prev[1]):
            raise ValueError(f"unsorted at index {i}")
    return None


def diff_events(old, new) -> dict:
    validate_stream(old)
    validate_stream(new)
    old_map = {event[1]: event for event in old}
    new_map = {event[1]: event for event in new}
    added = []
    moved = []
    changed = []
    for event in new:
        event_id = event[1]
        if event_id not in old_map:
            added.append(event_id)
        else:
            old_event = old_map[event_id]
            if event[0] != old_event[0]:
                moved.append(event_id)
            if event[2] != old_event[2]:
                changed.append(event_id)
    removed = []
    for event in old:
        event_id = event[1]
        if event_id not in new_map:
            removed.append(event_id)
    return {
        "added": added,
        "removed": removed,
        "moved": moved,
        "changed": changed,
    }


def merge_streams(a, b) -> list:
    validate_stream(a)
    validate_stream(b)
    merged = {}
    for event in a:
        merged[event[1]] = event
    for event in b:
        merged[event[1]] = event
    result = sorted(merged.values(), key=lambda event: (event[0], event[1]))
    return result
